window.__VISUAL_INDEX__([{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-2f0e5345418c8d93","w":119,"sc":"雨夜中的金属网格地面，表面湿润反光，中央横贯一条模糊的绿色发光带，左侧为深色砖墙，右侧为金属格栅，整体呈现冷色调的工业环境。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"your-name-2016","frame_id":"FG-b1d711f5e53407d0","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Your_Name_60.jpg","source_page":"https://film-grab.com/2026/07/13/your-name/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd2f.js","search_text":"画面采用低角度透视构图，视线沿地面向远处延伸，线条汇聚于上方。主体为占据画面绝大部分的湿滑金属地面，表面布满细密网格与接缝。一道横向的绿色光晕悬浮于地面中央，边缘模糊。左侧深色墙体与右侧金属结构形成夹道感，垂直雨丝贯穿画面，增强了空间的纵深感与潮湿氛围。\n这是一幅雨夜工业场景的写实画面。视角极低，贴近地面，展示了大面积湿润的金属网格地板，表面因雨水而呈现出强烈的镜面反射效果。画面中央横亘着一条模糊的、发着幽绿光芒的带状物体，光线在湿滑的地面上形成柔和的倒影。左侧是一堵深色的砖石墙壁，右侧则是带有长条孔洞的金属格栅结构，两者向远处延伸并汇聚。空中飘洒着细密的垂直雨丝，在冷蓝色的环境光下清晰可见。整体色调偏冷，以青灰色和深蓝色为主，绿色的光带是画面中唯一的暖色点缀，营造出一种潮湿、阴冷且带有科技感的氛围。\n","observed_resolution":"normal","observed_dimensions":[1920,1080],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-5ebaeed583554e71","w":119,"sc":"黑发少年上半身位于画面中央，双手抬起至脸颊两侧，嘴巴大张，面部泛红且挂着泪珠。背景为明亮的窗户和模糊的城市建筑，室内光线充足。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"your-name-2016","frame_id":"FG-c2dd5d6434d0195b","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Your_Name_20.jpg","source_page":"https://film-grab.com/2026/07/13/your-name/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd5e.js","search_text":"人物占据画面主体，头部与肩部清晰可见，双手手指弯曲悬空。背景通过大光圈虚化处理，突出了前景人物的情绪。光线从右侧窗户射入，在人物面部形成柔和的明暗过渡，色彩以暖色调为主，营造出一种紧张而感伤的氛围。\n动漫风格，一名黑发少年上半身特写，他双手抬起至脸颊两侧，手指微曲，嘴巴大张，神情激动，脸上挂着泪珠，面颊泛红。他身穿浅灰色T恤，背景是模糊的室内环境，右侧有大窗户，透进明亮的自然光，窗外可见淡蓝色的天空和模糊的城市建筑轮廓。画面色彩柔和，光影细腻，具有典型的日本动画电影质感。\n","observed_resolution":"normal","observed_dimensions":[1920,1080],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-8121171bb327c4f5","w":119,"sc":"阳光穿透森林，左侧坡地上站着两个微小的人影，右侧是密集的高大树木，前景有茂密的绿色灌木丛，整体环境被金色光束笼罩。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"your-name-2016","frame_id":"FG-e53abe492a83f40e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Your_Name_33.jpg","source_page":"https://film-grab.com/2026/07/13/your-name/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd81.js","search_text":"画面采用俯视视角，前景占据下方约三分之一，是失焦的绿色枝叶。中景左侧坡地上有两个极小的人影，仅能分辨站立姿态和大致轮廓，无法看清面部或手部细节。右侧是垂直排列的高大树木，树干细长。强烈的金色光束从左上角斜射而下，形成明显的光路效果，照亮了部分地面和树冠，营造出温暖而神秘的氛围。\n俯视视角的森林场景，前景是模糊的绿色灌木丛，占据画面下方。中景左侧的草坡上站着两个微小的人影，轮廓模糊，仅能看出站立姿态。右侧是密集的高大树木，树干细长垂直。强烈的金色阳光从左上角斜射入画面，形成清晰的光束，照亮了部分树冠和地面，营造出温暖、朦胧且充满光感的氛围。整体色调以绿色和金色为主，光影对比强烈，具有绘画质感。\n","observed_resolution":"normal","observed_dimensions":[1920,1080],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-d12410f64e86fb80","w":119,"sc":"一名穿深色西装、系浅蓝领带的黑发男子站立在车厢内，面部被斜射光线照亮。前景有模糊的乘客头部，右侧是延伸的金属扶手杆，背景可见车窗与模糊人影。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"your-name-2016","frame_id":"FG-f14f31e6ae76c683","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Your_Name_59.jpg","source_page":"https://film-grab.com/2026/07/13/your-name/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdd1.js","search_text":"画面主体为男子上半身，位于画面中央偏左。前景左下角有模糊的棕色头发头部，右侧多根金属扶手杆呈对角线延伸，形成空间层次。男子面部受光，左侧脸颊明亮，右侧处于阴影中，形成强烈的明暗对比。背景车厢内部光线柔和，整体色调偏冷，带有淡蓝色调。\n动漫风格，一名黑发年轻男子站立在地铁或电车车厢内，身穿深色西装外套，内搭白色衬衫，系着浅蓝色领带。男子面部朝向左前方，神情平静，面部左侧被强烈的暖色阳光照亮，右侧处于阴影中，形成鲜明的明暗对比。前景左下角有一个模糊的棕色头发人物头部背影，右侧有多根银色金属扶手杆呈对角线排列，延伸至画面深处。背景是车厢内部，可见车窗和模糊的乘客身影，整体色调偏冷，带有淡蓝色调，光线柔和，营造出一种静谧的氛围。\n","observed_resolution":"normal","observed_dimensions":[1920,1080],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-7962f73e609a8af3","w":4246,"sc":"一名戴帽人物背对镜头坐于树桩上，面向开阔的绿色高山草甸。远处山坡覆盖茂密针叶林，天空阴沉，草地上散布着零星牲畜与木屋。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-18afa1b8f3370da9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth060.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd79.js","search_text":"人物位于画面右侧前景，全身可见，坐于树桩上，身形在广阔环境中显得渺小。构图采用大远景，左侧前景有深色树木枝叶作为框架。光线柔和漫射，天空呈灰白色，山坡植被呈现深浅不一的绿色层次，整体色调偏冷且带有雾气感。\n写实风格的高山草甸全景，画面右侧前景一名戴宽檐帽、穿深色外套的人物背对镜头，坐在一截粗糙的树桩上。人物面向左侧开阔的绿色山坡，草地上散布着吃草的牲畜和几座深色木屋。背景是连绵起伏的山峦，覆盖着茂密的深绿色针叶林，山间弥漫着淡淡的雾气。天空阴沉，光线柔和漫射，左侧边缘有深色树枝作为前景遮挡，整体色调自然清冷，展现出宁静辽阔的自然氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-4054eab10a397bbc","w":4246,"sc":"高山草甸上，右侧矗立着木质缆车塔架与金属支架，一人站立于塔顶，一人攀爬梯子，地面站立着两名行人，左侧为起伏的绿色山坡。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-2e4120d3a56cd923","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth033.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd40.js","search_text":"画面采用广角低机位拍摄，右侧高耸的缆车设施占据显著视觉比重，与左侧平缓的山坡形成高低对比。人物全身可见，塔顶与梯上的人因高度显得较小，地面人物比例正常。光线明亮，天空呈现大面积蔚蓝，云层洁白，草地与土坡色彩自然，明暗对比清晰。\n这是一幅高山户外场景，右侧矗立着巨大的木质缆车塔架，塔顶有人站立，金属梯子上有人正在攀爬，旁边是高大的金属支架。地面中央站立着一名深色衣着的人，左侧远处有一名穿蓝衣红帽的人。背景是连绵起伏的绿色草坡，天空湛蓝，漂浮着大朵白云。阳光充足，光影清晰，展现了开阔的高原地貌与缆车设施的空间关系。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-1dcacbb74e5f1304","w":4246,"sc":"一名身披深红色斗篷的人物悬浮于画面中央，背对镜头。背景是连绵起伏的绿色山脉、远处的雪山峰顶以及布满厚重云层的天空，右下角有一座木质小屋。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-32ee4825d2a761b3","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth047.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd1d.js","search_text":"画面采用中心构图，人物位于视觉焦点，占据画面约三分之一高度。人物仅可见头部及上半身，下半身被斗篷遮盖，呈现悬浮状态。背景山脉呈对角线延伸，天空云层占据上半部分，光线柔和漫射，色彩以冷调的绿、灰、白为主，与人物鲜艳的红色斗篷形成强烈对比。\n一张写实风格的户外全景图，画面中央一名短发人物背对镜头悬浮在半空，身披宽大的深红色斗篷，斗篷下摆自然垂落。背景是开阔的高山草甸，两侧是覆盖着茂密植被的绿色山峦，远处可见白雪覆盖的山峰。天空布满厚重的灰白色云层，光线均匀柔和。右下角有一座深褐色木质小屋，屋顶呈浅色，周围点缀着紫色野花和绿色灌木。整体色调清冷，红色斗篷在冷色环境中显得格外醒目。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-c5fdd7240f57ed12","w":4246,"sc":"画面主体为开阔的绿色草坡，前景一名男子背对镜头站立，中景散布着约二十名穿着各异的人物，背景为茂密的针叶林带与阴沉天空。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-69ef862d925552cd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth059.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdc5.js","search_text":"构图采用广角全景，前景人物位于下方中央，中景人物呈散点分布，背景树林占据画面上部约三分之一。前景人物全身可见，中景人物多为全身或大半身，远景人物仅见轮廓。光线为阴天漫射光，无强烈阴影，色彩以草地的鲜绿、树林的深绿和天空的灰白为主，人物衣着颜色（黄、红、白）在绿色背景中形成视觉焦点。\n一张广角全景摄影作品，展现开阔起伏的绿色草坡。前景下方中央，一名身穿深色长袖上衣和灰色长裤的男子背对镜头站立，面向草坡。中景草地上散布着约二十名人物，姿态各异，有的站立，有的行走，有的坐卧，衣着颜色包括亮黄色、红色、白色和深色，在绿色背景中清晰可辨。背景是一排茂密的深绿色针叶林，林线起伏，上方是布满灰白云层的天空。光线柔和均匀，无强烈投影，整体色调自然写实，环境占比极大，人物在广阔空间中显得渺小。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-cd5ed4c79a81d4b7","w":4246,"sc":"石砌建筑与玻璃幕墙结构旁，一池清澈的静水倒映着周围的绿树与建筑，右侧林间草地上放置着白色躺椅，环境幽静自然。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-6de46d37ca70f48e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth034.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdcd.js","search_text":"画面采用平视角度，构图以水平线为主，水面占据画面下半部分，形成清晰的倒影。左侧建筑体量较大，石墙纹理粗糙，上方玻璃结构反射出绿色植被。右侧树木茂密，光线从树冠间洒下，形成斑驳的光影。整体色调以绿色和灰色为主，光线柔和，营造出宁静、自然的氛围。\n画面展示了一处宁静的自然景观，左侧是一座现代风格的石砌建筑，墙面由不规则石块堆砌而成，上方是透明的玻璃幕墙，反射着周围的绿色植被。建筑前方是一池清澈的静水，水面如镜，清晰地倒映着建筑和树木的轮廓。右侧是茂密的树林，阳光透过树叶洒下斑驳的光影，草地上放置着两把白色的躺椅，椅背朝向水面。前景是绿色的草地和散落的石块，整体色调清新自然，光线柔和，营造出一种静谧、放松的氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-1bb2e1c3e8290e58","w":4246,"sc":"一位白发戴眼镜的年长男性，身着深色西装与白衬衫，面带微笑。背景为大面积复古花纹墙纸，画面右侧及顶部有大面积黑色阴影。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-80babe90e5795dd1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth008.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd1b.js","search_text":"人物位于画面右侧，头部及肩部以上可见，身体略微向左侧转。背景占据画面左侧约三分之二，呈现米黄色底色的繁复花卉图案。光线从人物左前方投射，照亮面部及西装左肩，右侧面部及背景右侧逐渐隐入黑暗，形成强烈的明暗对比。\n一位满头白发的年长男性，戴着深色粗框眼镜，身穿深灰色西装外套、白色衬衫并系着深色领带。他面带温和的微笑，目光看向镜头。人物位于画面右侧，身体略微侧向左边。背景是带有复古风格的米黄色墙纸，上面印有深褐色和绿色的繁复花卉与藤蔓图案。画面采用低调照明，光线集中在人物面部和左侧背景上，画面右侧和顶部边缘有大面积的黑色阴影，营造出一种沉静、复古的氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-fa6900c115ca7936","w":4246,"sc":"透过金属圆形孔洞，可见一名戴黑色面罩与头巾的人物面部，背景为花纹墙纸，周围被大面积模糊的暗色金属表面包围。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-86295f6d5b411fe1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth007.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdfa.js","search_text":"构图采用中心对称的框景式布局，圆形孔洞将视线聚焦于人物面部。人物仅头部及肩部可见，面部被黑色面罩遮挡，仅露出双眼与嘴唇。孔洞边缘呈现金属光泽，底部有强烈反光。整体色调偏黄绿，光线昏暗，营造出压抑、窥视的视觉氛围。\n透过一个巨大的圆形金属孔洞窥视，孔洞边缘呈现模糊的金属质感，底部有一处明亮的白色反光。孔洞内部清晰可见一名人物，头戴黑色头巾，面部佩戴黑色面罩，仅露出双眼和嘴唇，眼神直视前方。人物背景是带有复古花纹的米黄色墙纸。画面整体笼罩在黄绿色的昏暗光线下，孔洞外的金属表面大面积虚化，形成强烈的景深对比，营造出一种窥视感和神秘压抑的氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-ce0d34ae3a7ba09c","w":4246,"sc":"画面右侧一名赤裸上身的人物仰头向上，腰腿部围着浅色布料，左下方有一张低垂的男性面孔，背景为大面积纯黑。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261011","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-952796732d66ef5f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth021.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdce.js","search_text":"构图极度不对称，右侧人物占据主要视觉重心，左下方面孔孤立存在。右侧人物上半身及大腿可见，呈坐姿或蹲姿，身体轮廓在黑暗中清晰。左下方仅面部可见，呈俯视角度。光线为强烈的侧顶光，仅照亮人物局部，形成高对比度，肤色呈暖黄褐色，其余部分隐没于黑暗。\n极度昏暗的低调摄影画面，背景为纯黑。右侧一名赤裸上身的男性人物，身体呈坐姿，头部大幅度后仰，面部朝向左上方，胸肌与腹部轮廓在侧光下清晰可见，腰部围着浅色布料。左下方远处有一张低垂的男性面孔，双眼向下看，神情凝重。光线仅照亮人物局部，呈现暖黄褐色调，大面积阴影与黑色背景融合，营造出压抑、神秘的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-6592d75bac61d785","w":4246,"sc":"昏暗室内空间，中央一人坐于台阶边缘，周围分布着站立或坐着的几个人影，背景为深色墙壁，整体氛围压抑。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-d24b9d6aa6bbc59e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth020.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd65.js","search_text":"画面采用中心构图，主体人物位于画面中央偏下，全身可见，呈坐姿。周围人物轮廓模糊，大小不一，显示距离差异。光线从下方或前方投射，形成强烈的明暗对比，人物面部和身体部分被照亮，其余部分隐没在黑暗中。色调偏暖，以棕色和黑色为主，营造出一种神秘而紧张的氛围。\n昏暗的室内空间，中央有一人坐在台阶边缘，全身可见，姿态放松。周围有几个人影，有的站立，有的坐着，轮廓模糊，大小不一。背景是深色的墙壁，光线从下方或前方投射，形成强烈的明暗对比，人物面部和身体部分被照亮，其余部分隐没在黑暗中。色调偏暖，以棕色和黑色为主，营造出一种神秘而紧张的氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-1bbd5eb52edf1c17","w":4246,"sc":"夜间户外，一名穿白衬衫黑西装的男子坐在白色长椅上，身体后仰，面部表情痛苦。前景左侧有模糊的黑色人影背影，背景是昏暗的建筑轮廓。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"youth-2015","frame_id":"FG-f1b17b02c2dee5f9","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/youth046.jpg","source_page":"https://film-grab.com/2019/04/14/youth/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd1b.js","search_text":"画面采用过肩视角，前景左侧黑色人影占据约三分之一画面，形成遮挡。主体人物位于画面中右侧，上半身可见，坐姿后仰，头部偏向左侧。光线从上方投射，照亮人物面部和白色衬衫，与周围黑暗环境形成强烈明暗对比。背景建筑处于焦外虚化状态，整体色调偏冷，以黑、白、灰为主。\n夜间户外场景，画面左侧前景是一个模糊的黑色人物背影，占据画面左部。中景右侧，一名男子坐在白色长椅上，身穿白色衬衫、黑色领带和深色西装外套，身体向后倾斜，头部歪向一侧，面部表情显得痛苦或虚弱。背景是模糊的深色建筑轮廓和植被，光线昏暗，主要光源照亮了男子的面部和白色衬衫，形成强烈的明暗对比，整体氛围压抑。\n","observed_resolution":"normal","observed_dimensions":[1280,546],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-9ed3a205332ed67f","w":4247,"sc":"一名戴三角帽、穿紫红色外套的人物侧身站立在岩石高地上，面向左侧宽阔的河流，河面上有一艘白色帆船，远处是低矮的绿色植被带。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-1b52e1d7100c5abc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_020.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd9e.js","search_text":"人物位于画面右侧三分之一处，全身可见，侧身面向左侧，占据画面高度约三分之一。河流横贯画面中部，占据约三分之一面积，天空占据上方三分之一。光线为阴天漫射光，整体色调偏冷灰，人物紫红色外套在灰绿环境中形成色彩对比。岩石表面纹理粗糙，呈浅褐色。\n一名戴浅色三角帽、穿紫红色长外套和绿色裤子的男子侧身站立在浅褐色岩石高地上，面向左侧，全身可见，占据画面右侧三分之一。前方是宽阔平静的灰褐色河流，河面左侧有一艘白色三角帆船。远处地平线是低矮的绿色灌木植被带。天空布满灰白色云层，光线柔和均匀。前景岩石表面粗糙有裂纹，右侧有一棵稀疏的小树。整体色调偏冷灰，人物外套颜色在环境中较为突出。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-c369541bf59b788a","w":4247,"sc":"宽阔的河流与沙滩，天空布满云层。左侧一人站立，一人坐于枯木上；中间三人站立或行走；右侧一人骑马，一人站立。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-2447db4644e82fd1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_036.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdc3.js","search_text":"画面采用广角远景构图，地平线位于下方约三分之一处，天空占据大部分画面。人物全身可见，身形在广阔环境中显得渺小。光线为柔和的漫射光，天空云层层次丰富，地面沙滩色调均匀，水面平静。\n一张写实风格的广角远景照片，展现了宽阔的河流与沙滩场景。天空占据画面约三分之二，布满层层叠叠的白色与灰色积云，透出些许蓝天。下方是平静的宽阔水面，远处有一条绿色的树林地平线。前景是平坦的浅褐色沙滩。画面左侧，一名男子站立在伸入水中的枯木上，旁边一人坐在木头上。画面中央，三个人影在沙滩上站立或行走，其中一人身穿红色上衣。画面右侧，一人骑在马上，旁边站着一名赤膊男子。整体光线柔和，色彩自然，人物在广阔环境中显得渺小。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-e99201a51f7eecd4","w":4247,"sc":"一名男子坐在木桌前，背对镜头，身体前倾，似乎正在伏案书写。背景是斑驳的土黄色墙壁，光线昏暗，氛围沉静。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-28268b5cd597a3e1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_005.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vde9.js","search_text":"画面采用过肩视角，主体人物占据画面右侧及中心大部分区域，呈现上半身背影。人物身穿米色马甲和浅色长袖衬衫，坐在深色木椅上。左侧木桌上堆放着纸张，旁边插着几根白色羽毛。环境光线昏暗，主要光源似乎来自左前方，照亮了人物的背部和桌面，背景墙壁呈现出粗糙的纹理和深浅不一的污渍，整体色调偏暖黄与深褐。\n昏暗室内，一名深色短发男子背对镜头坐在深色木椅上，身穿米色粗布马甲和浅色长袖衬衫，身体前倾伏在粗糙的木桌上。桌面上散乱堆放着泛黄的纸张，左侧插着几根白色的羽毛笔。背景是斑驳陈旧的土黄色墙壁，布满污渍和纹理。光线从左侧微弱射入，照亮人物背部和桌面，营造出一种沉静、压抑且充满年代感的氛围，画面色调以深褐、米黄和暗灰为主。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-8744b578a1d7e4b6","w":4247,"sc":"一名身穿暗红色上衣的男子侧身坐在一间破败昏暗的房间内，周围是剥落的墙壁和堆叠的杂物，背景有一扇敞开的门通向明亮的室外。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-43e5a7ed53c84969","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_021.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd87.js","search_text":"画面采用暗调处理，室内光线极弱，主要光源来自背景敞开的门洞，形成强烈的逆光效果。人物位于画面左侧，仅上半身可见，呈侧坐姿态，面部处于阴影中。右侧前景有模糊的垂直结构遮挡，增加了画面的纵深感。整体色调偏冷且压抑，明暗对比强烈，突出了破败环境的质感。\n昏暗破败的室内场景，一名男子身穿暗红色长袖上衣，侧身坐于画面左侧，身体微向前倾，面部处于阴影中，仅可见侧脸轮廓。背景是一面斑驳剥落的墙壁，中间有一扇敞开的门，门外透入明亮的自然光，可见模糊的树木。右侧前景有模糊的垂直木柱遮挡，旁边堆叠着米色麻袋和深色木箱，右下角可见几本堆叠的旧书。整体光线昏暗，高对比度，冷色调，营造出压抑、陈旧的氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-2a147ce4e9bcb48f","w":4247,"sc":"昏暗浑浊的黄褐色环境中，左侧可见一只大型猫科动物（似虎）的头部与长须，右下方有一道弯曲的亮色肢体或物体横亘，背景完全隐没于黑暗。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-7f19751259092b30","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_004.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd2a.js","search_text":"画面极度昏暗，主体被浓重的黄褐色雾气或阴影笼罩。左侧虎头占据约三分之一画面，长须清晰可见，眼神在暗处微亮。右下方的亮色弯曲物体（似肢体或绳索）与暗部形成对比。整体采用低角度或平视，光线微弱且单一，色彩层次极少，仅存黄褐与深黑，营造出压抑、神秘且充满张力的视觉氛围。\n一张极度昏暗的写实画面，整体笼罩在浑浊的黄褐色雾气中。画面左侧是一只大型猫科动物（似虎）的头部特写，面部轮廓在阴影中若隐若现，长长的白色胡须清晰可见，眼睛在黑暗中微微反光。画面右下方有一道弯曲的亮色物体（似肢体或绳索）横亘，与周围的深黑色背景形成强烈对比。环境几乎完全隐没在黑暗中，没有明确的光源方向，色彩仅由黄褐、深黑和少许亮白构成，营造出一种压抑、神秘且充满原始野性的视觉感受。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-a84f33b5ddb43990","w":4247,"sc":"昏暗沙地上，多名赤裸上身的人物与深色动物躯体交错躺卧，姿态松弛，环境空旷，光线极弱，呈现静谧的休息状态。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-7f995a098df75f00","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_035.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vda8.js","search_text":"画面采用俯视角度，人物与动物在沙地上呈散点式分布。前景人物下半身裹着条纹布料，侧卧可见全身；中景人物赤裸上身，倚靠在深色动物躯体上；远处人物仅见轮廓。整体光线昏暗，色彩饱和度低，以冷灰色调为主，明暗对比微弱，细节隐没在阴影中。\n昏暗沙地上的休息场景，俯视视角。前景一名赤裸上身男子侧卧，下半身裹着红白条纹布料，头部枕在深色动物躯体旁。中景一名男子赤裸上身，穿着深色长裤，身体横卧在深色动物背上，姿态放松。左侧一名男子穿着浅色短裤，侧身躺卧。远处沙地上还有两名人物，一人仰卧，一人侧卧，轮廓模糊。环境为平坦沙地，光线极弱，整体色调偏冷灰，明暗对比低，人物与动物交错分布，呈现静谧的夜间或黎明氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-6eca101e8c97f7bc","w":4247,"sc":"昏暗室内，左侧一男一女并排坐于深色雕花座椅上，右侧前景站立一人背对镜头，中间小圆桌上摆放着酒瓶与玻璃杯，背景为深蓝色墙面。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-ac08d45ee8811e14","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_012.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd6e.js","search_text":"画面采用过肩视角，右侧前景人物背部占据约三分之一画幅，形成视觉遮挡。左侧男女坐姿端正，仅上半身及大腿部分可见，人物面部受光较亮，与深色背景形成对比。整体色调偏冷，光线柔和，营造出一种静谧且略带压抑的室内氛围。\n昏暗的室内场景，背景为深蓝色墙面。画面左侧，一名身穿暗红色外套、绿色裤子的男子与一名身穿浅粉色束腰长裙、头戴高耸白色卷发假发的女子并排坐在深色雕花座椅上，两人均面向右侧。画面右侧前景，一名身穿深色格纹长裙的人物背对镜头站立，身体占据右侧大部分空间。两人中间的小圆桌上摆放着深色玻璃酒瓶、陶罐及几个装有液体的玻璃杯。光线柔和，人物面部清晰，整体色调偏冷，呈现出一种古典而静谧的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-ac9dae3f5151d676","w":4247,"sc":"一名赤裸上身、头部涂红的人物骑在马上，位于画面中央。周围是茂密的高草和散落的棕榈树，天空阴沉，整体呈现开阔的野外环境。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-c781ac30e40d29dc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_027.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdac.js","search_text":"画面采用中心构图，人物与马匹位于视觉焦点。人物上半身及头部清晰可见，下半身被高草遮挡，马匹仅露出头部和部分躯干。镜头视角接近平视，光线为阴天漫射光，无强烈阴影。色彩以枯黄的草地、灰绿的树木和灰白天空为主，人物头部的红色形成视觉对比。\n在阴沉天空下的野外，一名赤裸上身、头部涂红的人物骑在马上，位于画面中央。周围是茂密的高草和散落的棕榈树，天空阴沉，整体呈现开阔的野外环境。画面采用中心构图，人物与马匹位于视觉焦点。人物上半身及头部清晰可见，下半身被高草遮挡，马匹仅露出头部和部分躯干。镜头视角接近平视，光线为阴天漫射光，无强烈阴影。色彩以枯黄的草地、灰绿的树木和灰白天空为主，人物头部的红色形成视觉对比。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-70993b7a9c9a0a4f","w":4247,"sc":"一位金发卷发女性面部特写，佩戴长耳坠，身着浅色花纹服饰，正凝视着画面右侧前景中背对镜头的深红衣领人物，背景为模糊的室内环境。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-dac7fc4f0086b225","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_013.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd70.js","search_text":"画面采用过肩视角，焦点清晰地落在左侧女性面部，右侧前景人物背部及肩部占据画面约三分之一，形成明显的景深遮挡。光线柔和偏冷，从左侧照亮女性面部，使其五官立体，而右侧人物处于暗部，仅见轮廓。整体色调低沉，营造出一种私密且略带压抑的对话氛围。\n一位金发女性面部特写，头发梳成复古的卷曲盘发，佩戴着精致的长款深色耳坠，身穿浅色带有暗纹的复古服饰。她神情专注，眼神略带忧郁地凝视着画面右侧。右侧前景是一个背对镜头的人物，仅可见其深红色的衣领和肩部轮廓，处于失焦状态。背景是模糊的室内空间，光线柔和且偏冷调，从左侧照亮女性面部，形成细腻的明暗过渡，整体氛围沉静而具有戏剧张力。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-e9671d96b8cd07ef","w":4247,"sc":"几名面部涂满红色颜料的人物聚集在户外，中央人物头戴高耸的编织头饰，周围人物赤裸上身，背景为模糊的绿色植被。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zama-2017","frame_id":"FG-fda32c94d36ea560","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/Zama_028.jpg","source_page":"https://film-grab.com/2021/04/15/zama/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vde9.js","search_text":"画面采用过肩视角，前景左右两侧有模糊的人物背影作为框架，将视线引向中央。中央人物上半身可见，头戴高耸的编织头饰，面部布满皱纹且涂有红色颜料，神情严肃。右侧人物同样面部涂红，赤裸上身，皮肤在光线下呈现油亮质感。背景人物面部模糊，整体光线昏暗，色调偏暖红，营造出一种原始、神秘且压抑的视觉氛围。\n昏暗光线下，几名面部涂满红色颜料的人物聚集在户外。画面中央是一位年长男性，头戴高耸的编织头饰，面部皱纹深刻，神情严肃，赤裸上身，皮肤呈现古铜色。右侧一名年轻男性同样面部涂红，赤裸上身，皮肤在光线下显得油亮。前景左右两侧有模糊的人物背影作为框架，背景是模糊的绿色植被。整体色调偏暖红，光线集中在人物面部，营造出一种原始、神秘且压抑的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1280,720],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-789febd3f5b29870","w":4248,"sc":"高耸的室内长廊，顶部为拱形玻璃天窗，两侧是多层木质墙面与窗户，地面铺有浅色地砖，数名人物在走廊中行走，空间纵深感极强。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zazie-dans-le-metro-1960","frame_id":"FG-32621750ac99543f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1347).jpg","source_page":"https://film-grab.com/2013/06/17/zazie-dans-le-metro/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd78.js","search_text":"采用高角度俯视构图，视线沿走廊中轴线向深处延伸，形成强烈的透视引导。前景人物全身可见，身形较小，远处人影逐渐缩小直至模糊。顶部玻璃天窗透入冷白自然光，照亮地面与走廊中央，两侧木质墙面呈现暖褐色调，明暗对比清晰，营造出幽深、肃穆的空间氛围。\n高角度俯视视角的室内长廊场景，顶部是巨大的拱形玻璃天窗结构，由黑色金属框架支撑，透入明亮的冷白色自然光。走廊两侧是多层对称的木质墙面，呈暖褐色，分布着矩形窗户，部分窗户挂着白色帘布。地面铺设浅色几何图案地砖，向画面深处延伸。走廊中央有数名人物正在行走，前景可见两名全身人物，一人穿深色长衣，一人穿浅色衣物，身形较小；远处走廊中散布着更多模糊的人影，随距离增加而变小。画面中央有一道横向的黑色金属栏杆横跨走廊，带有装饰性花纹。整体色调偏暖黄与冷白交织，空间纵深感极强，光线从顶部均匀洒下，营造出古老、庄严且略带压抑的建筑氛围。\n","observed_resolution":"low","observed_dimensions":[748,574],"observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-d4a8c844c958fbdd","w":4248,"sc":"室内餐厅场景，一名穿红衣男子与穿红衣儿童分坐圆桌两侧，中间站着一名穿蓝衣围裙的女子，背景是挂着窗帘的窗户和装饰物。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zazie-dans-le-metro-1960","frame_id":"FG-759043f5d18e2fad","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1320).jpg","source_page":"https://film-grab.com/2013/06/17/zazie-dans-le-metro/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdd4.js","search_text":"画面采用平视角度，构图以圆桌为中心。前景可见圆桌及三人上半身，人物占据画面主要空间。光线柔和，色调偏暖黄，背景窗帘透光形成明亮背景，与前景人物形成对比。\n室内暖色调餐厅场景，画面中央是一张圆形木桌，桌上摆放着碗盘和酒杯。桌子左侧坐着一名穿红衣的儿童，右侧坐着一名穿红色花纹外套的男子，两人均面向桌子。桌子后方站着一名穿蓝绿色上衣和白色围裙的女子，身体微微前倾。背景是透光的米色窗帘，窗前立着一尊深色人形雕塑，右侧有黄色花卉装饰，上方悬挂着白色球形灯罩。\n","observed_resolution":"low","observed_dimensions":[748,574],"observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-6071c48251c73111","w":4248,"sc":"一名留着浓密棕色八字胡的男子面部占据画面绝大部分，双眼圆睁，神情惊讶。背景为模糊的浅色与暗色块，环境细节不可辨。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zazie-dans-le-metro-1960","frame_id":"FG-7978e3c0f7c8e8cf","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1344).jpg","source_page":"https://film-grab.com/2013/06/17/zazie-dans-le-metro/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd60.js","search_text":"画面为极近距离的人像，仅可见人物面部及颈部、肩部少许衣物。人物面部位于画面正中，头部几乎填满画框，头顶与下巴接近边缘。背景完全虚化，呈浅灰与暗褐的模糊色块，无具体物体。光线从正面偏上方照射，面部受光均匀，肤色偏暖，眼部与鼻部有高光，阴影柔和。\n低分辨率彩色画面，极近距离拍摄一名男子面部，占据画面主体。男子深色头发向后梳理，额头宽阔，眉毛浓密，双眼圆睁，瞳孔深褐，眼神直视前方，表情呈现惊讶或错愕。面部中央有浓密的棕色八字胡，向两侧下垂。身穿灰色格纹西装外套，内搭白色衬衫领口。背景完全虚化，呈浅灰与暗褐的模糊色块，无具体物体。光线从正面偏上方照射，面部受光均匀，肤色偏暖，眼部与鼻部有高光，阴影柔和。\n","observed_resolution":"low","observed_dimensions":[748,574],"observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-d18636005270674f","w":4248,"sc":"拥挤的街道交通场景中，一辆浅蓝色敞篷车异常地叠压在一辆黑色轿车车顶之上，车内挤满多名乘客，周围环绕着各式老式汽车、卡车与面包车。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zazie-dans-le-metro-1960","frame_id":"FG-82322f777ece30ca","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1317).jpg","source_page":"https://film-grab.com/2013/06/17/zazie-dans-le-metro/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdd1.js","search_text":"采用高角度俯视构图，画面主体为中央叠压的两辆汽车。浅蓝色敞篷车内可见约七至八名乘客，仅上半身可见，姿态为坐姿，衣着颜色各异，包括橙色、黑色与米色。周围车辆密集排列，形成复杂的几何色块。光线为自然日光，明暗对比适中，色彩以车辆的灰、蓝、黑及地面的土黄色为主，层次丰富。\n高角度俯视视角的拥挤街道交通场景。画面中心是一辆浅蓝色老式敞篷车，车身异常地叠压在一辆黑色轿车车顶之上，形成垂直堆叠结构。蓝色车内挤满多名乘客，仅上半身可见，穿着橙色、黑色、米色等衣物，呈坐姿。周围环绕着密集的老式车辆，包括左侧的深灰色轿车、右侧的米色轿车、后方的银灰色面包车以及左上角的黄色卡车头。地面为土黄色，车辆排列紧凑，光影自然，色彩呈现复古的灰、蓝、黑与土黄色调，画面分辨率较低，具有明显的颗粒感。\n","observed_resolution":"low","observed_dimensions":[748,574],"observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-59a8e64dde89ff9d","w":4248,"sc":"画面主体为一名男子的面部，占据绝大部分视野。背景可见模糊的蓝绿色与红白条纹色块，人物头部上方有深色帽檐遮挡，左侧边缘有一处模糊的肉色突起。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zazie-dans-le-metro-1960","frame_id":"FG-c3baccccae205ebc","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1208).jpg","source_page":"https://film-grab.com/2013/06/17/zazie-dans-le-metro/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd59.js","search_text":"构图极度紧凑，人物面部几乎填满整个画幅，环境背景被压缩至边缘。人物头部略微前倾，视线直视前方。光线从正面偏上方投射，在额头、鼻梁和脸颊形成明显的高光区域，眼窝和鼻翼下方有较深的阴影。色彩以暖色调的皮肤为主，与背景冷色调形成对比。\n这是一张极度近距离的人物面部画面，主体为一名男子的脸部，占据了画面的绝大部分空间。人物头部上方被深色帽檐遮挡，面部皮肤呈现暖色调，额头、鼻梁和脸颊受光明显，形成高光，眼窝和鼻翼下方有阴影。背景处于失焦状态，左侧可见模糊的蓝绿色块，右侧有红白相间的条纹色块。画面左侧边缘有一处模糊的肉色突起。整体光线柔和，色彩层次丰富，人物面部轮廓清晰，五官比例夸张，呈现出一种强烈的视觉冲击力。\n","observed_resolution":"low","observed_dimensions":[748,574],"observation_limits":["源画面最长边不足800像素，仅描述可辨的大轮廓、环境、构图和光色；细节待复核"],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-da98627f39c0a11f","w":4249,"sc":"昏暗室内，一名红发女子侧身坐在桌前，目光专注地凝视着左前方亮起的电脑屏幕，背景处于深暗之中。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-229acea17dac3cb7","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/47 (1311).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdda.js","search_text":"人物位于画面右侧，呈现上半身及头部侧面轮廓，身体朝向左侧。左侧前景有两台显示器，屏幕发出冷白光，照亮了人物的面部和发丝。背景大面积黑暗，仅上方有模糊的暗色物体轮廓。整体明暗对比强烈，光源主要来自屏幕，营造出一种专注且压抑的视觉氛围。\n昏暗的室内环境，一名红发女子位于画面右侧，侧身坐着，面部朝向左侧。她身穿深色外套，神情专注地凝视着左前方的电脑屏幕。左侧前景有两台显示器，屏幕显示着模糊的地图或数据界面，发出冷白色的光，成为主要光源，照亮了女子的侧脸和发丝。背景几乎完全处于黑暗中，只有上方隐约可见一些模糊的物体轮廓。画面明暗对比强烈，冷色调的屏幕光与周围的黑暗形成鲜明反差，营造出一种静谧而紧张的氛围。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-9befbc4e194c8d9d","w":4249,"sc":"俯瞰视角下的长条形花园水渠，两侧排列着高大的棕榈树和修剪整齐的草坪，远处延伸至朦胧的树林与建筑，几名游客在水渠边行走或停留。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-2a939cd9d24aa022","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/21 (1348).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd9b.js","search_text":"画面采用高角度俯拍，长条形水渠从前景向远处延伸，形成强烈的透视引导线。水渠两侧是茂密的棕榈树林，左侧草坪上有修剪成球形的灌木。画面中可见数名人物，全身可见，姿态为行走或站立，人物在画面中占比极小。光线柔和，整体色调偏绿，远处景物因大气透视而显得朦胧，明暗对比不强烈，色彩层次丰富。\n高角度俯拍视角，一条笔直的长条形水渠从画面底部向中心延伸，水渠两侧是宽阔的浅色石板步道。步道两旁是修剪整齐的绿色草坪，草坪上点缀着深绿色的球形灌木和高大的棕榈树，棕榈树树干细长，树冠茂密。画面右侧前景有一棵高大的针叶树，枝叶繁茂，遮挡了部分视线。水渠和步道上有零星的游客，全身可见，姿态为行走或站立，人物在画面中显得很小。远处是茂密的树林和隐约可见的建筑，背景天空灰白，整体光线柔和，色调以绿色和灰白色为主，呈现出一种宁静、开阔的氛围。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-0428df78035a2fd0","w":4249,"sc":"昏暗室内，一名红发女子侧身面向右侧，头部裹着浅色头巾，身穿深色外套，背景几乎全黑，右侧边缘可见模糊的亮色窗格结构。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-3ee617e8408b5e16","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1348).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd04.js","search_text":"人物上半身及面部清晰可见，占据画面中央偏左位置，身体朝向右侧。背景大面积黑暗，右侧边缘有垂直的亮色条带，疑似窗户或光源。光线从右侧照射，照亮人物面部右侧及头巾边缘，左侧面部及身体陷入阴影，形成强烈的明暗对比。整体色调偏冷，以黑、灰、暗绿为主，仅面部和头巾受光处呈现暖色。\n昏暗室内场景，一名红发女子侧身面向右侧，头部裹着浅色头巾，身穿深色外套，仅上半身及面部可见。背景大面积黑暗，右侧边缘有模糊的垂直亮色条带，疑似窗户。光线从右侧照射，照亮人物面部右侧及头巾边缘，左侧面部及身体陷入阴影，形成强烈明暗对比。整体色调偏冷，以黑、灰、暗绿为主，仅面部和头巾受光处呈现暖色。人物表情平静，眼神专注，画面氛围沉静而神秘。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-e2fc188420384231","w":4249,"sc":"昏暗室内，一名红发女性面部特写，神情凝重，背景虚化模糊，仅见微弱暖色光斑。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-42435f231034cffa","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/34 (1345).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vde2.js","search_text":"画面主体为女性面部，占据画面约80%面积，仅可见头部及颈部上方。采用侧脸特写构图，人物视线向左下方。光线从左侧打入，形成强烈的明暗对比，面部右侧及背景陷入深重阴影。发丝在光线下呈现红褐色调，皮肤质感在侧光下清晰可见，整体色调偏冷暗，仅左侧有微弱暖光。\n昏暗环境下的女性面部特写，红褐色长发凌乱垂落，侧脸轮廓清晰，眼神向下凝视，神情忧郁凝重。强烈的侧光从左侧照亮面部，鼻梁与脸颊受光，右脸及背景完全隐没在深黑色阴影中。背景极度虚化，仅左下角有模糊的暖色光斑。画面色调低沉，红发与苍白皮肤在暗调中形成对比，皮肤纹理与发丝细节在光影中清晰可见，营造出压抑且静谧的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-2f78ea70faf6ea46","w":4249,"sc":"一名佩戴战术头盔与通讯设备的男性士兵上半身，面部朝向画面左侧，背景为昏暗的深色网格状结构。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-537672e2784b639f","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/60 (1194).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd2f.js","search_text":"画面主体为士兵上半身，占据画面左侧及中央大部分区域，右侧背景留白。人物头部佩戴带有黄色支架和亮灯的战术头盔，颈部围着浅色面罩。光线从右侧照射，形成强烈的明暗对比，面部右侧受光，左侧隐入黑暗。背景虚化，呈现出深色的菱形网格纹理，整体色调偏冷且压抑。\n一名男性士兵的上半身特写，他佩戴着复杂的战术头盔，头盔侧面有黄色支架和发光的白色小灯，颈部围着浅色面罩，身穿迷彩战术背心。人物面部朝向左侧，神情凝重，皮肤上有汗水或污渍。背景是模糊的深色菱形铁丝网结构。强烈的侧光从右侧打在人物面部和肩部，形成高对比度的明暗效果，画面整体色调阴暗、冷峻，具有电影质感。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-c834acc7e3226946","w":4249,"sc":"昏暗室内，一名卷发胡须男子位于左侧，面部清晰可见，右侧前景为模糊的人影轮廓，背景有微弱光斑。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-65f35165a9e54290","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/08 (1321).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdc8.js","search_text":"画面采用过肩视角，左侧男子占据主要视觉空间，右侧前景人物背部与头部形成大面积虚化遮挡。光线从左侧投射，照亮男子面部，形成强烈的明暗对比。色调偏暖黄，背景深邃，营造出私密且压抑的对话氛围。\n昏暗室内场景，左侧一名卷发络腮胡男子，身穿深色圆领上衣，面部受光清晰，神情凝重。右侧前景为极度虚化的人物头部与肩部轮廓，占据画面右半部分，形成强烈的景深遮挡效果。背景昏暗，左后方有模糊的冷色光斑。暖黄色侧光勾勒男子面部轮廓，整体色调低沉，光影对比强烈，呈现出电影般的质感。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-ffa5ae05fe979407","w":4249,"sc":"黄昏或黎明时分，一座清真寺宣礼塔的剪影矗立在深蓝色天空中，前景是建筑物的暗色屋顶轮廓，画面呈现静谧的剪影效果。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-8351b22fe11f6f6e","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1321).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdff.js","search_text":"画面以深蓝色渐变天空为背景，占据约三分之二面积。前景右下方是建筑物的暗色屋顶和墙体，形成对角线分割构图。宣礼塔位于画面中右部，呈剪影状，塔顶圆顶和尖顶装饰清晰可辨。整体光线极暗，建筑物几乎完全处于阴影中，仅天空呈现从深蓝到浅蓝的渐变层次，营造出宁静肃穆的氛围。\n黄昏或黎明时分的清真寺剪影画面，深蓝色渐变天空占据大部分画面，从顶部深蓝过渡到底部浅蓝。画面右下方是建筑物的暗色屋顶轮廓，呈对角线延伸，屋顶边缘清晰。中右部矗立着一座清真寺宣礼塔的剪影，塔身细长，顶部有圆顶和尖顶装饰，塔身中部有拱形窗洞轮廓。前景右侧有暗色墙体遮挡部分视野。整体光线极暗，建筑物完全处于阴影中，仅天空呈现蓝色渐变，画面静谧肃穆，剪影效果明显。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-690c9e67910c4734","w":4249,"sc":"一名戴帽男子蹲坐在路边土坡上，身披棕色毯子，背对镜头望向远处。背景是模糊的公路，可见白色轿车和橙色卡车，右侧有绿色灌木，天空阴沉。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-c619275133c329d2","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/46 (1318).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd69.js","search_text":"人物位于画面右侧，呈蹲坐姿态，全身可见，头部戴深色圆帽，肩披棕色流苏毯子，下着浅色长裤。人物占据画面约三分之一宽度。背景车辆与远山处于失焦状态，形成景深对比。光线为阴天漫射光，整体色调偏冷灰，人物棕色衣物与背景形成色彩对比。\n一名男子蹲坐在路边土坡上，背对镜头，头戴深色圆帽，肩披棕色流苏毯子，身穿深绿色上衣和浅色长裤，身体微微前倾。人物位于画面右侧，占据约三分之一宽度。前景是干燥的土坡草地，背景是失焦的公路，可见一辆白色轿车和一辆橙色卡车，远处有模糊的山影。画面右侧有绿色灌木枝叶。天空阴沉灰白，光线柔和漫射，整体色调偏冷，人物棕色衣物在灰调背景中较为突出。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-b2154419c6d14353","w":4249,"sc":"夜间绿色调画面，背景为亮窗建筑，前景五个人物剪影在空地上行走，右侧有树木与电线杆，整体氛围昏暗神秘。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-d5b0203f7ded60bd","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/59 (1209).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vdb2.js","search_text":"构图横向展开，人物位于画面中下部，呈剪影状，仅能辨识大致轮廓与行走姿态，无法看清面部或衣着细节。背景建筑占据上半部分，窗户透出强光，形成高对比度。画面整体笼罩在绿色夜视色调中，光源来自建筑内部及外部路灯，明暗层次分明，前景地面较暗，人物与背景分离清晰。\n夜间绿色夜视风格画面，背景是一栋两层建筑，窗户透出明亮黄绿色光，建筑前有电线杆和树木。前景空地上有五个人物剪影，呈行走姿态，身形模糊，仅见轮廓。人物大小不一，近处者较大，远处者较小，整体处于背光状态。地面平坦昏暗，右侧有灌木丛，整体色调统一为深绿，光影对比强烈，氛围静谧而紧张。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-142bee24d30ec4dc","w":4249,"sc":"昏暗环境中，一名红发人物面部侧影位于画面左侧，背景为深黑色，散布着数个失焦的圆形光斑，前景下方有一条模糊的浅色横向结构。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zero-dark-thirty-2012","frame_id":"FG-ef9a83655f4c9ae1","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1345).jpg","source_page":"https://film-grab.com/2014/10/17/zero-dark-thirty/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd14.js","search_text":"人物面部占据画面左侧约三分之一，仅可见头部侧面轮廓，身体其余部分隐没在黑暗中。背景大面积留黑，右侧分布着三个明显的圆形散景光斑，分别为红色和蓝灰色。左侧人物面部旁有一个橙色光斑。光线极暗，仅微弱侧光勾勒出人物鼻梁、额头和发丝边缘，整体呈现低调摄影风格，光色对比强烈。\n昏暗夜景，画面左侧一名红发人物面部侧影，仅可见头部轮廓，微弱侧光勾勒鼻梁与发丝，眼神凝视前方。背景为深黑色，右侧散布着失焦的圆形光斑，包括一个红色光点和两个蓝灰色光点，左侧人物旁有一个橙色光点。前景下方有一条模糊的浅色横向结构，整体氛围压抑神秘，低调摄影风格，高对比度，散景效果明显。\n","observed_resolution":"normal","observed_dimensions":[1920,1036],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-34bc62bfcdd023b0","w":4250,"sc":"昏暗室内，一名男子侧身站立，双手正在左侧墙面上整理或粘贴纸张，背景深处有一盏壁灯发出暖黄光晕。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-09b212142424c5ef","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/57 (1235).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd34.js","search_text":"画面采用侧面视角，人物占据右侧约二分之一画幅，仅可见上半身及手臂。左侧墙面贴满纸张，形成视觉引导。背景处于焦外虚化，壁灯是主要光源，投射出暖黄色调，与前景的暗部形成强烈明暗对比，营造出静谧且略带压抑的氛围。\n昏暗的室内场景，一名深色短发男子位于画面右侧，侧身面向左方，身穿深色长袖上衣，内搭格纹衬衫。他抬起双臂，双手正在左侧墙壁上操作，似乎在粘贴或整理多张印有图案的纸张。左侧墙面占据前景，纸张细节清晰。背景深处有一盏壁灯，发出柔和的暖黄色光晕，照亮了部分墙壁，其余区域笼罩在阴影中。整体色调偏暗，以深褐与暖黄为主，光影对比强烈，营造出一种专注且私密的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,425],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-a8ecd051c0c7b659","w":4250,"sc":"昏暗室内，前景一名穿白衬衫打条纹领带的男子低头站立，左后方远处一名男子站立，右侧门口逆光处另一名男子站立，左侧悬挂一盏米色灯罩吊灯。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-344ed821e934e2fb","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/33 (1346).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vda8.js","search_text":"画面以前景男子为主体，占据右侧大部分空间，仅可见上半身，头部微低。左后方人物全身可见但模糊，右侧门口人物受强光照射呈剪影状。室内光线昏暗，色调偏暖黄，右侧窗户透入强烈白光形成高对比度，左侧吊灯提供局部照明，整体明暗反差强烈。\n昏暗的室内场景，暖黄色调。前景右侧一名灰发男子身穿白色短袖衬衫，系深色条纹领带，胸前口袋插有笔，低头向下看，仅上半身可见。左后方远处一名深色头发男子穿白衬衫站立，身影模糊。右侧门口处另一名男子穿白衬衫打领带，被窗外强光照射呈半剪影状态。左侧悬挂一盏米色锥形灯罩的吊灯。背景有窗帘和木质墙壁，室内光线昏暗，右侧窗户透入明亮白光，形成强烈明暗对比。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-a2f94407021340d3","w":4250,"sc":"三名男子站立在一栋粉白相间的建筑外墙旁，背景可见远处的山脉、树木和停放的车辆，光线明亮。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-42b242bbc0c8cdf5","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/32 (1346).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vda2.js","search_text":"画面采用横向构图，左侧大面积被建筑外墙占据，三名男子位于画面中右侧。人物仅上半身可见，最右侧男子身形最高大，中间男子次之，左侧男子较矮。光线从右侧照射，在人物面部和衣物上形成明暗对比，整体色调偏暖，背景天空呈现淡蓝色。\n这是一张写实风格的户外场景图。画面左侧是一栋老旧建筑的侧墙，墙面由木板和粉白相间的砖块组成，带有垂直的窗框结构。画面右侧站立着三名男子，均穿着浅色衬衫和领带。最右侧男子身材高大，双手叉腰，侧脸看向左方；中间男子头发卷曲，侧身站立；左侧男子戴着眼镜，身形较矮，正低头看向下方。背景远处有绿色的树木、连绵的山脉以及停放在路边的几辆汽车。阳光从右侧照射，在人物身上投下清晰的阴影，整体色彩自然，具有胶片质感。\n","observed_resolution":"normal","observed_dimensions":[1024,425],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-8b83beaf3fe858a6","w":4250,"sc":"画面中央是一台老式方形电影摄影机，被固定在金属支架上。摄影机四周环绕着四个巨大的圆形强光灯，背景为昏暗的室内空间，整体呈现出一种复古的拍摄现场氛围。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-4c4ab7a6d8fb560a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/19 (1348).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd8b.js","search_text":"构图采用严格的中心对称布局，摄影机位于画面正中，四个圆形光源分别占据四角，形成稳定的视觉框架。摄影机主体呈深灰色金属质感，镜头部分清晰可见。四个光源发出强烈的白光，带有明显的水平方向镜头光晕，与暗色背景形成极高对比。画面整体色调偏冷，以黑白灰为主，光线层次分明，营造出一种工业感和仪式感。\n这是一张复古风格的摄影棚内部画面。画面正中央是一台老式方形电影摄影机，机身呈深灰色，镜头朝向观众，安装在黑色的金属支架上。摄影机的四周分布着四个巨大的圆形强光灯，分别位于画面的左上、右上、左下和右下角。这些灯光发出耀眼的白光，并伴有强烈的水平方向镜头光晕，光线在画面中形成十字交叉的视觉效果。背景是昏暗的室内环境，隐约可见墙壁和天花板结构。整体色调偏冷，以黑白灰为主，光影对比强烈，营造出一种专业且神秘的拍摄现场氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-674254b4b5243b0d","w":4250,"sc":"昏暗档案室内，一名蓄须男子侧身坐于桌前，面前摊开文件。背景深处，另一人影正背对镜头沿通道向里走去，两侧是密集的档案柜。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-5ca95303ce839f2c","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/20 (1349).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd67.js","search_text":"画面采用侧向构图，前景男子占据右侧约三分之一区域，仅上半身及侧脸可见，面部轮廓在微弱侧光下清晰。背景人物位于画面中央偏左的通道深处，身形较小且模糊。整体光线极暗，主要光源来自左侧，形成强烈的明暗对比，色调偏冷且低饱和度，营造出压抑、静谧的氛围。\n昏暗的档案室内部，前景右侧一名留着胡须的男子侧身坐着，身穿深色外套，面部朝向左侧，神情凝重。他面前的深色桌面上摊开着一本文件。背景是两排高耸的木质档案柜，中间形成一条狭窄的通道。在通道深处，一个模糊的人影正背对镜头向里走去。整体光线昏暗，仅有微弱的光线从左侧照亮前景男子的侧脸和桌面，大部分环境笼罩在阴影中，色调偏冷，呈现出一种压抑且静谧的视觉质感。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-8d32556e71e4fe4e","w":4250,"sc":"夜间空旷街道，一辆黄色轿车停在路边，车门开启，一名深色衣着人物站在车旁，周围大面积黑暗，路面有白色标线。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-9ae113de155c9b96","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/06 (1322).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd8d.js","search_text":"高角度俯视构图，黄色轿车位于画面中右侧，是视觉焦点。人物全身可见，站立于驾驶位车门处，身形在车旁显得较小。环境占比极大，左侧为空旷路面，右侧及上方被浓重阴影覆盖。光线昏暗，仅照亮车辆与局部路面，形成强烈的明暗对比，色调以黑黄为主。\n夜间高角度俯视画面，空旷街道被大面积黑暗笼罩。画面中右侧停着一辆黄色轿车，车身在昏暗中显得醒目，驾驶位车门打开。一名身穿深色衣物的人物站在车门旁，全身可见，身形较小。左侧路面可见白色标线，延伸至画面边缘。整体光线极暗，仅照亮车辆与人物周围区域，形成强烈的明暗对比，色调以黑色阴影与黄色车身为主，营造出静谧且压抑的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-5ede6b1089cd4ad5","w":4250,"sc":"昏暗车厢内，两名男子并排而坐。右侧男子手握方向盘，侧脸朝向右方；左侧男子位于前景，面部大半处于阴影中，背景可见模糊的红色与黄色光斑。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-c8033029d1f2a517","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/07 (1322).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd5e.js","search_text":"画面采用极低调照明，整体笼罩在深黑色中。右侧男子占据画面中右部，上半身可见，侧脸轮廓被微弱光线勾勒，手部握持方向盘清晰可见。左侧男子位于前景左侧，仅露出头部与肩部，面部大部分隐没在黑暗中。背景透过车窗可见散焦的暖色光点，与前景的冷暗色调形成对比，营造出压抑、神秘的夜间氛围。\n昏暗的车厢内部，两名男子并排坐着。右侧男子身穿浅色外套，侧脸朝向右方，右手握在方向盘上，面部轮廓在微弱光线下清晰可见。左侧男子位于前景，身穿深色衣物，面部大半处于阴影中，仅露出部分五官轮廓。背景透过车窗可见模糊的红色与黄色光斑，整体色调偏暗，以黑色和深褐色为主，营造出压抑、神秘的夜间氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,423],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-6ade1fe9f2a87453","w":4250,"sc":"两名男子在灰白色石柱建筑内面对面站立，左侧男子穿深色外套配红领结，右侧男子穿深蓝色连帽外套，背景深处可见一模糊人影。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-c9b4b55a38025f24","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/44 (1328).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd6a.js","search_text":"画面采用平视视角，两名男子占据前景左右两侧，形成对峙式构图。左侧男子可见上半身，右侧男子可见上半身及肩部。环境为高大的灰白色石质建筑内部，立柱与墙面占据背景大部分空间。光线柔和偏冷，整体色调呈青灰色，人物面部受光均匀，背景深处有自然光透入，形成明暗层次。\n两名男子面对面站立于灰白色石质建筑内部，左侧男子卷发，穿深色外套内搭白衬衫系红褐色领结，右侧男子短发，穿深蓝色连帽外套内搭格纹衬衫，两人均侧脸相对。背景为高大的石柱与浅色墙面，建筑空间开阔，远处通道尽头有一模糊人影站立。整体色调偏冷呈青灰色，光线柔和均匀，人物面部有自然光照明，环境明暗对比适中，画面呈现冷静克制的视觉氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,425],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-23130f6b4b2388c3","w":4250,"sc":"双手按压在暖黄色平面上，背景为模糊的灰蓝色衣物色块，画面聚焦于手指细节与皮肤纹理，环境虚化。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261008","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-e028fbe0c4f23d4a","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/45 (1326).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd23.js","search_text":"画面主体为两只手，仅可见手部及部分前臂，人物身体其余部分不可见。双手位于画面中下部，手指自然弯曲按压在物体表面。背景完全虚化，呈现灰蓝色调，与前景暖黄色形成冷暖对比。光线柔和，从上方或侧方照射，在手指关节处形成自然阴影，皮肤纹理清晰可见。\n双手按压在暖黄色平面上，手指自然弯曲，指甲修剪整齐，皮肤纹理清晰，指关节处有柔和阴影。背景为完全虚化的灰蓝色衣物色块，与前景形成冷暖色调对比。光线柔和自然，从上方照射，突出手部立体感。画面聚焦于手部细节，景深极浅，背景完全模糊，仅保留色块轮廓。整体色调温暖，氛围安静专注。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"},{"size":"","angle":"","frame":"","lens_type":"","dof":"","ld":"","time":"","weather":"","ie":"","pos":"","move":[],"light":[],"loc":[],"color":[],"comp":[],"emo":[],"id":"VS-6315a71df80878c4","w":4250,"sc":"昏暗室内，两名男子隔桌对坐交谈。左侧男子卷发，右侧男子短发，桌上有瓶罐和文件，背景悬挂多盏暖色吊灯。","pl":"","ep":"","pal":[],"fk":"","st":"待核","add":"20261010","origin":"visual","source_work_id":"zodiac-2007","frame_id":"FG-f617b7bf4f024119","source_url":"https://film-grab.com/wp-content/uploads/photo-gallery/thumb/58 (1222).jpg","source_page":"https://film-grab.com/2010/06/23/zodiac/","verification":"观图待人工核","tag_status":"待标注","detail_file":"vd63.js","search_text":"画面呈现两人上半身及桌面，背景环境占比约三分之一。构图采用平视角度，人物左右对称分布。光线主要来自上方悬挂的暖黄色吊灯，形成明显的明暗对比，人物面部受光，背景较暗。色调偏暖，以黄褐色为主，营造出一种私密、专注的氛围。\n昏暗的室内场景，两名男子坐在桌前面对面交谈。左侧男子留着深色卷发，身穿深蓝色长袖上衣，身体前倾，右手抬起做手势。右侧男子留着深色短发，身穿浅色格纹衬衫，双手交叠在桌上，神情专注地看向对方。桌面上摆放着调味瓶、玻璃杯和摊开的文件。背景是模糊的室内空间，天花板上悬挂着多盏发着暖黄光的吊灯，光线柔和地洒在人物身上，营造出一种温暖而私密的氛围。\n","observed_resolution":"normal","observed_dimensions":[1024,424],"observation_limits":[],"selection":"来源画面均匀采样，代表性待人工精选"}]);